import Foundation
import StripeSpec

// stripe-gen — generates the Swift models, request-parameter structs, and
// typed client methods from the pinned Stripe OpenAPI definition.
//
// Usage: swift run stripe-gen [outdir]
// Outdir defaults to the package root. Generated files land in
// Sources/StripeModels/Generated and Sources/StripeClient/Generated. CI
// regenerates and fails on any diff.

func fail(_ message: String) -> Never {
  FileHandle.standardError.write((message + "\n").data(using: .utf8)!)
  exit(1)
}

let arguments = Array(CommandLine.arguments.dropFirst())
let root = arguments.first ?? "."

do {
  let spec = try StripeSpec.loadRaw()
  let schemas = try SpecParse.schemas(from: spec)
  let paths = try SpecParse.paths(from: spec)

  let emitter = TypeEmitter()
  emitter.seedInliner(schemas: schemas)

  // Phase 1: response objects — every component schema becomes a type.
  // Sorted keys keep regeneration deterministic.
  for key in schemas.keys.sorted() {
    let schema = schemas[key] ?? [:]
    let bucket = TypeEmitter.bucket(forSchemaKey: key)
    _ = emitter.swiftType(
      for: schema,
      fallbackName: emitter.nameForSchemaKey(key),
      bucket: bucket
    )
  }

  // Phase 2: operations — params structs, list containers, client methods.
  let ops = try OpCollector.collect(schemas: schemas, paths: paths)
  let endpointEmitter = EndpointEmitter(emitter: emitter)

  var opsByBucket: [String: [OpRequest]] = [:]
  for op in ops {
    opsByBucket[TypeEmitter.bucket(forSchemaKey: op.resourceSchemaKey), default: []].append(op)
  }

  var serviceFiles: [(bucket: String, code: String)] = []
  for bucket in opsByBucket.keys.sorted() {
    let bucketOps = (opsByBucket[bucket] ?? []).sorted { a, b in
      if a.resourceClassName != b.resourceClassName {
        return a.resourceClassName < b.resourceClassName
      }
      if a.methodType != b.methodType { return a.methodType < b.methodType }
      return a.path < b.path
    }
    let code = try endpointEmitter.serviceExtension(for: bucketOps, bucket: bucket)
    serviceFiles.append((bucket, code))
  }

  // Phase 3: write files.
  let fileManager = FileManager.default
  let modelsDir = root + "/Sources/StripeModels/Generated"
  let clientDir = root + "/Sources/StripeClient/Generated"
  try fileManager.createDirectory(atPath: modelsDir, withIntermediateDirectories: true)
  try fileManager.createDirectory(atPath: clientDir, withIntermediateDirectories: true)

  // Clear previously generated files so removals in the spec propagate.
  for directory in [modelsDir, clientDir] {
    for entry in try fileManager.contentsOfDirectory(atPath: directory) {
      let path = directory + "/" + entry
      var isDirectory: ObjCBool = false
      if fileManager.fileExists(atPath: path, isDirectory: &isDirectory), isDirectory.boolValue {
        try fileManager.removeItem(atPath: path)
      } else {
        try fileManager.removeItem(atPath: path)
      }
    }
  }

  let header = """
    //
    //  Generated by stripe-gen from the pinned Stripe OpenAPI definition
    //  (release \(StripeSpec.pinnedSourceRelease), API version \(StripeSpec.pinnedAPIVersion)).
    //  Do not edit by hand: rerun `swift run stripe-gen`.
    //
    import Foundation

    """

  // Group generated types by bucket into files.
  var byBucketFile: [String: [GeneratedType]] = [:]
  for type in emitter.types + endpointEmitter.params + endpointEmitter.lists {
    byBucketFile[type.bucket, default: []].append(type)
  }
  for bucket in byBucketFile.keys.sorted() {
    let types = byBucketFile[bucket] ?? []
    let body = types.map(\.code).joined(separator: "\n\n")
    try (header + body + "\n").write(
      toFile: modelsDir + "/Objects+\(bucket).swift",
      atomically: true,
      encoding: .utf8
    )
  }
  for (bucket, code) in serviceFiles {
    let clientHeader = header + "import StripeModels\n\n"
    try (clientHeader + code + "\n").write(
      toFile: clientDir + "/Services+\(bucket).swift",
      atomically: true,
      encoding: .utf8
    )
  }

  // Stamp the generation inputs so CI and humans can see what ran.
  let stamp = """
    apiVersion: \(StripeSpec.pinnedAPIVersion)
    sourceRelease: \(StripeSpec.pinnedSourceRelease)
    schemas: \(schemas.count)
    operations: \(ops.count)
    generatedTypes: \(emitter.types.count + endpointEmitter.params.count + endpointEmitter.lists.count)
    unknownSchemaShapes: \(emitter.unknowns.count)
    """
  try stamp.write(toFile: modelsDir + "/generation-stamp.txt", atomically: true, encoding: .utf8)

  print(
    "stripe-gen: \(ops.count) operations, "
    + "\(emitter.types.count + endpointEmitter.params.count + endpointEmitter.lists.count)"
    + " types generated"
  )
  if !emitter.unknowns.isEmpty {
    for unknown in emitter.unknowns.sorted().prefix(20) {
      print("  unresolved: \(unknown)")
    }
  }
} catch {
  fail("stripe-gen failed: \(error)")
}
